const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',route:'M4 5a2 2 0 1 0 4 0a2 2 0 1 0-4 0 M16 19a2 2 0 1 0 4 0a2 2 0 1 0-4 0 M8 5h7a4 4 0 0 1 0 8H9a3 3 0 0 0 0 6h7',daily:'M5 5h14v16H5z M9 3h6v4H9z M8 13l3 3 5-6',journal:'M4 3h15v18H4z M8 3v18 M11 8h5 M11 12h4',repeat:'M20 8a8 8 0 0 0-14-2L3 9 M3 4v5h5 M4 16a8 8 0 0 0 14 2l3-3 M21 20v-5h-5',skills:'M3 18v-4h4v4z M10 18V9h4v9z M17 18V4h4v14z',jobs:'M3 7h18v14H3z M8 7V4h8v3 M3 12q9 5 18 0 M11 13h2',clock:'M21 12a9 9 0 1 1-18 0a9 9 0 1 1 18 0 M12 6v6l4 2',fire:'M12 2c0 6-5 7-4 12-2-1-2-3-2-4-5 8 2 13 7 11 8-2 7-9 3-13 1 3-1 4-2 4 1-4 0-7-2-10z',arrow:'M4 12h15 M14 7l5 5-5 5',book:'M3 5q5-2 9 1 5-3 9-1v14q-5-2-9 1-4-3-9-1z M12 6v14',cal:'M3 5h18v16H3z M7 3v4 M17 3v4 M3 10h18',activity:'M2 13h5l3-8 4 14 3-7h5'};
const ic=k=>'<svg aria-hidden="true" class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round"><path d="'+paths[k]+'"/></svg>';
const navs={home:'Обзор',route:'Учебный маршрут',daily:'Задания на день',journal:'Журнал ошибок',repeat:'Повторение',skills:'Мои навыки',jobs:'Вакансии'};
const key='hpc-track-v1',today=()=>dateKey(new Date()),dateKey=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-'),later=n=>{let d=new Date();d.setDate(d.getDate()+n);return dateKey(d)};
let state=Object.assign({checks:{},notes:{},done:[],skills:[],logs:[],reviews:{},daily:{},plans:{},activity:{}},JSON.parse(localStorage.getItem(key)||'{}'));
const save=()=>localStorage.setItem(key,JSON.stringify(state)),touch=()=>{state.activity[today()]=(state.activity[today()]||0)+1;save()};
const C=window.course, lessons=C.flatMap((m,i)=>m.lessons.map((l,j)=>({...l,i,j,id:i+'-'+j}))),lesson=id=>lessons.find(l=>l.id===id),next=()=>lessons.find(l=>!state.done.includes(l.id))||lessons[0],due=()=>Object.keys(state.reviews).filter(k=>state.reviews[k].date<=today()),dialog=$('#dialog'),closeDialog=()=>dialog.close();
let routeFilter='Все темы',page='home';
function nav(ids){return ids.map(k=>'<a href="#'+k+'" class="'+(k===page?'active':'')+'">'+ic(k)+navs[k]+'</a>').join('')}
function title(t,p){return '<h1>'+t+'</h1><p class="intro">'+p+'</p>'}
function terrain(){
const P=(x,y)=>{let z=64*Math.exp(-(((x-.17)/.54)**2+((y+.15)/.56)**2))+38*Math.exp(-(((x+.6)/.48)**2+((y-.4)/.5)**2));return [(220+x*112+y*76).toFixed(2),(142+y*43-x*19-z*1.42).toFixed(2)]};
let g='';for(let axis=0;axis<2;axis++)for(let n=-18;n<=18;n++){let pts=[];for(let m=-36;m<=36;m++)pts.push((axis?P(n/18,m/36):P(m/36,n/18)).join(','));g+='<polyline points="'+pts.join(' ')+'"/>'}
const peak=P(.17,-.15);return '<svg class="terrain" viewBox="0 0 455 212" preserveAspectRatio="xMidYMid slice" aria-label="Координатная сетка с поверхностью функции"><defs><pattern id="dots" width="13" height="13" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".7" fill="#879b72" opacity=".5"/></pattern></defs><rect width="455" height="212" fill="url(#dots)"/><g fill="none" stroke="#6a835a" stroke-width=".7">'+g+'</g><g stroke="#ed824a" stroke-width="1.4"><path d="M'+peak[0]+' '+peak[1]+'v-25h25" fill="none"/><circle cx="'+peak[0]+'" cy="'+peak[1]+'" r="3.8" fill="#ef8048"/></g><g fill="#68805b" font-size="9" font-family="monospace"><text x="263" y="32">z = f(x,y)</text><text x="404" y="181">x</text><text x="46" y="184">y</text></g><g stroke="#899b79" fill="none" stroke-width="1"><path d="M18 23v-7h7 M429 16h7v7 M18 185v7h7 M429 192h7v-7"/></g></svg>'}
function plan(){let day=today();if(!state.plans[day]){state.plans[day]={id:next().id,review:due()[0]||state.done.at(-1)||next().id};save()}return state.plans[day]}
function tasks(){let p=plan(),l=lesson(p.id),r=lesson(p.review);return [{title:l.title,meta:C[l.i].name+' · Урок',time:15,id:l.id},{title:'Практика: '+l.title,meta:C[l.i].name+' · Упражнение',time:20,id:l.id},{title:'Самопроверка: '+r.title,meta:C[r.i].name+' · Повторение',time:5,id:r.id}]}
function dailyPanel(){let d=state.daily[today()]||[],date=new Intl.DateTimeFormat('ru',{weekday:'long',day:'numeric',month:'long'}).format(new Date());return '<div class="panel"><div class="paneltop"><h2>Задания на сегодня</h2><span class="tag">'+d.length+' / 3</span></div><div class="dayline">'+date[0].toUpperCase()+date.slice(1)+'</div>'+tasks().map((t,i)=>'<div class="task"><button class="check '+(d.includes(i)?'checked':'')+'" aria-label="Отметить задание" aria-pressed="'+d.includes(i)+'" onclick="toggleTask('+i+')">'+(d.includes(i)?'✓':'')+'</button><div><button class="taskname" onclick="taskOpen('+i+')">'+esc(t.title)+'</button><div class="taskmeta">'+esc(t.meta)+'</div></div><span class="tasktime">'+ic('clock')+' '+t.time+' мин</span></div>').join('')+(page==='home'?'<a class="footlink" href="#daily">Все задания →</a>':'')+'</div>'}
function toggleTask(i){let d=state.daily[today()]||=[];if(d.includes(i))d.splice(d.indexOf(i),1);else{d.push(i);touch()}save();render()}
function taskOpen(i){let t=tasks()[i];openLesson(t.id,i)}
function streak(){let n=0,d=new Date();if(!state.activity[dateKey(d)])d.setDate(d.getDate()-1);while(state.activity[dateKey(d)]){n++;d.setDate(d.getDate()-1)}return n}
function activity(){
  const index=(new Date().getDay()+6)%7;
  const days=['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'];
  const counts=days.map((_,i)=>(state.daily[later(i-index)]||[]).length);
  const total=counts.reduce((a,b)=>a+b,0);
  const bars=counts.map((count,i)=>'<div class="weekcol" title="'+days[i]+' · '+count+' из 3 заданий"><i style="height:'+count/3*100+'%"></i></div>').join('');
  return '<div class="panel"><div class="paneltop"><h2>Активность</h2><span class="tiny">Эта неделя</span></div><div class="dayline">Недельная цель · 21 задание</div><div class="weekchart">'+bars+'</div><div class="days">'+days.map((day,i)=>'<span class="'+(i===index?'currentday':'')+'">'+day+'</span>').join('')+'</div><div class="chartnote"><i class="dot"></i> Выполнено '+total+' из 21</div></div>';
}
function home(){let l=next(),pct=Math.round(state.done.length/lessons.length*100);return title('Учебный центр','Ваш маршрут в высокопроизводительные вычисления.')+'<section class="hero">'+terrain()+'<div class="eyebrow"><i></i> ТЕКУЩИЙ МОДУЛЬ · '+String(l.i+1).padStart(2,'0')+' / 09</div><h2>'+(l.i===0?'Основы C++':esc(C[l.i].name))+'</h2><p>'+esc(l.title)+' · Урок '+(l.j+1)+' из '+C[l.i].lessons.length+'</p><button class="primary" onclick="openLesson(\''+l.id+'\')">'+(state.done.length?'Продолжить обучение':'Начать обучение')+' '+ic('arrow')+'</button></section><div class="stats"><div class="stat"><div class="label">'+ic('route')+' Прогресс маршрута</div><div class="metric">'+pct+'<small> %</small></div><div class="bar"><i style="width:'+pct+'%"></i></div></div><div class="stat"><div class="label">'+ic('book')+' Пройдено уроков</div><div class="metric">'+state.done.length+' <small>/ '+lessons.length+'</small></div><div class="statfoot">В девяти модулях</div></div><div class="stat"><div class="label">'+ic('fire')+' Серия занятий</div><div class="metric">'+streak()+' <small>дн.</small></div><div class="statfoot">Дней практики подряд</div></div></div><div class="grid">'+dailyPanel()+activity()+'</div><div class="row"><h2 class="sectiontitle">Учебный маршрут</h2><a href="#route" class="dailybtn">Все модули →</a></div><div class="practicegrid">'+C.slice(0,3).map((m,i)=>'<button class="panel" style="text-align:left" onclick="toModule('+i+')"><div class="row"><span class="num">0'+(i+1)+'</span>'+ic('arrow')+'</div><h3 style="margin-top:12px">'+esc(m.name)+'</h3><p>Уроков пройдено: '+state.done.filter(id=>id.startsWith(i+'-')).length+' / '+m.lessons.length+'</p></button>').join('')+'</div>'}
function filters(){return '<div class="filters">'+['Все темы',...C.map(m=>m.name)].map((n,i)=>'<button class="filter '+(routeFilter===n?'sel':'')+'" onclick="filterTopic('+i+')">'+esc(n)+'</button>').join('')+'</div>'}
function filterTopic(i){routeFilter=i?C[i-1].name:'Все темы';render()}
function toModule(i){routeFilter=C[i].name;location.hash='route'}
function noteField(id) {
  return '<label class="form">Мой ответ и результаты практики<textarea class="study-note" oninput="saveNote(\''+id+'\',this.value)" placeholder="Запишите прогноз, результат запуска или причину расхождения.">'+esc(state.notes[id]||'')+'</textarea></label>';
}
function saveNote(id,text){state.notes[id]=text;save()}
function routeView(skills=false) {
  const activeModule=next().i;
  const sections=C.map((module,i)=>{
    if(routeFilter!=='Все темы' && routeFilter!==module.name)return '';
    const selected=skills?state.skills:state.done;
    const items=skills?module.skills:module.lessons;
    const count=items.filter((_,j)=>selected.includes(i+'-'+j)).length;
    const rows=items.map((item,j)=>{
      const id=i+'-'+j;
      if(skills)return '<label class="skillcheck"><input type="checkbox" '+(selected.includes(id)?'checked':'')+' onchange="toggleSkill(\''+id+'\');this.closest(\'details\').querySelector(\'.module-count\').textContent=this.closest(\'details\').querySelectorAll(\'input:checked\').length+\' / '+items.length+'\'">'+esc(item)+'</label>';
      return '<button class="lessonrow" onclick="openLesson(\''+id+'\')"><span><small class="tiny">'+String(j+1).padStart(2,'0')+'</small>　'+esc(item.title)+'</span><span class="arrow">'+(selected.includes(id)?'✓':'→')+'</span></button>';
    }).join('');
    const score=state.checks[i]?.score;
    const test=skills?'':'<button class="secondary spacer" onclick="openCheck('+i+')">Проверка модуля · '+(score===undefined?'3 вопроса':score+' / 3')+'</button>';
    return '<section class="panel"><details class="module-accordion" '+(routeFilter!=='Все темы'||activeModule===i?'open':'')+'><summary><span class="num">'+String(i+1).padStart(2,'0')+'</span><h2>'+esc(module.name)+'</h2><span class="tag module-count">'+count+' / '+items.length+'</span></summary>'+rows+test+'</details></section>';
  }).join('');
  return title(navs[page],skills?'Отмечайте навыки, которые можете применить самостоятельно.':lessons.length+' уроков в девяти модулях. После практики проверьте себя без подсказок.')+filters()+'<div class="stack">'+sections+'</div>';
}
function toggleSkill(id){state.skills=state.skills.includes(id)?state.skills.filter(x=>x!==id):[...state.skills,id];save()}
function modal(html){dialog.innerHTML=html;if(!dialog.open)dialog.showModal()}
const dialogTop=t=>'<div class="row"><span class="eyebrow">'+esc(t)+'</span><button class="close" aria-label="Закрыть" onclick="closeDialog()">×</button></div>';
function openLesson(id,task=null){let l=lesson(id);modal(dialogTop(C[l.i].name+' / Урок '+(l.j+1))+'<h2>'+esc(l.title)+'</h2><p>'+esc(l.explanation)+'</p><pre><code>'+esc(l.code)+'</code></pre><h3>Практика</h3><p>'+esc(l.task)+'</p><h3>Самопроверка</h3><p>'+esc(l.check)+'</p>'+noteField(id)+'<details><summary>Сверить ответ</summary><p>'+esc(l.answer)+'</p></details><div class="row spacer"><button class="secondary" onclick="errorForm('+l.i+',\''+id+'\')">Записать ошибку</button><button class="primary" onclick="finishLesson(\''+id+'\','+task+')">'+(task===1?'Завершить практику':task===2?'Завершить самопроверку':state.done.includes(id)?'Урок пройден ✓':'Завершить урок')+'</button></div>')}
function finishLesson(id,task){if((task===0||task===null)&&!state.done.includes(id)){state.done.push(id);state.reviews[id]={step:0,date:later(1)};touch()}let d=state.daily[today()]||=[];let n=task??(plan().id===id?0:null);if(n!==null&&!d.includes(n)){d.push(n);touch()}if(task===2&&state.reviews[id]?.date<=today())schedule(id,true);save();closeDialog();render()}
function journal(){return title(navs.journal,'Фиксируйте причину ошибки и рабочее решение, чтобы вернуться к слабым темам.')+'<button class="primary spacer" onclick="errorForm(0)">+ Записать ошибку</button>'+filters()+'<section class="panel"><h2>Записи</h2>'+(state.logs.filter(x=>routeFilter==='Все темы'||C[x.i].name===routeFilter).reverse().map(x=>'<article class="weak"><span class="tag">'+esc(C[x.i].name)+'</span> <small class="tiny">'+esc(x.date)+'</small><h3>'+esc(x.error)+'</h3><p>'+esc(x.fix)+'</p></article>').join('')||'<p class="empty">Пока нет записей. Добавьте ошибку из практики и укажите, что помогло её исправить.</p>')+'</section>'}
function errorForm(i,sourceId=null){modal(dialogTop('Журнал ошибок')+'<h2>Новая запись</h2><form id="errform"><label class="form">Слабая тема<select name="topic">'+C.map((m,j)=>'<option value="'+j+'" '+(i===j?'selected':'')+'>'+esc(m.name)+'</option>').join('')+'</select></label><label class="form">Где возникла ошибка?<textarea required name="error" maxlength="2000"></textarea></label><label class="form">Решение или следующий шаг<textarea required name="fix" maxlength="2000"></textarea></label><button class="primary">Сохранить запись</button></form>');$('#errform').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),i=Number(f.get('topic'));state.logs.push({i,error:f.get('error'),fix:f.get('fix'),date:today()});let id=(sourceId && lesson(sourceId)?.i===i ? lesson(sourceId) : null) || lessons.find(l=>l.i===i&&!state.done.includes(l.id))||lessons.find(l=>l.i===i);state.reviews[id.id]={step:0,date:today()};save();closeDialog();render()}}
function schedule(id,ok){let r=state.reviews[id];r.step=ok?Math.min(4,r.step+1):0;r.date=later([1,3,7,14,30][r.step]);touch()}
function reviewCard(id){let l=lesson(id);modal(dialogTop('Повторение · '+C[l.i].name)+'<h2>'+esc(l.title)+'</h2><p>'+esc(l.check)+'</p><details><summary>Показать ответ</summary><p>'+esc(l.answer)+'</p></details><div class="row spacer"><button class="secondary" onclick="reviewResult(\''+id+'\',false)">Повторить завтра</button><button class="primary" onclick="reviewResult(\''+id+'\',true)">Вспомнил</button></div>')}
function reviewResult(id,ok){schedule(id,ok);closeDialog();render()}
function repeatView(){let entries=Object.entries(state.reviews).sort((a,b)=>a[1].date.localeCompare(b[1].date));return title('Повторение','Первое повторение — через день после урока. Успешные ответы увеличивают интервал до 3, 7, 14 и 30 дней.')+'<section class="panel spacer"><div class="paneltop"><h2>Карточки для повторения</h2><span class="tag">На сегодня: '+due().length+'</span></div>'+(entries.map(([id,r])=>'<button class="lessonrow" onclick="reviewCard(\''+id+'\')"><span>'+esc(lesson(id).title)+'</span><span class="tag">'+(r.date<=today()?'Сегодня':r.date)+'</span></button>').join('')||'<p class="empty">Завершите первый урок или добавьте запись в журнал ошибок. Здесь появится вопрос для самопроверки.</p>')+'</section>'}
function render(){let old=page;page=location.hash.slice(1)||'home';if(!navs[page])page='home';if(old!==page){window.scrollTo(0,0);if(page!=='route')routeFilter='Все темы'}document.body.classList.remove('navopen');$('#learn').innerHTML=nav(['home','route','daily','journal','repeat']);$('#career').innerHTML=nav(['skills','jobs']);$('#crumb').textContent=navs[page];$('#page').innerHTML=page==='home'?home():page==='route'?routeView():page==='skills'?routeView(true):page==='journal'?journal():page==='repeat'?repeatView():page==='daily'?title(navs.daily,'Небольшой учебный блок на каждый день: урок, практика и проверка знаний.')+'<div class="grid">'+dailyPanel()+activity()+'</div>':title('Вакансии','Удалённые позиции и сравнение требований с вашими навыками.')+'<div id="joblist" class="spacer"></div>';if(page==='jobs')window.renderJobs($('#joblist'),C.filter((m,i)=>m.skills.every((_,j)=>state.skills.includes(i+'-'+j))).map(m=>m.name))}
window.addEventListener('hashchange',render);$('.menu').onclick=()=>document.body.classList.toggle('navopen');dialog.addEventListener('click',e=>{if(e.target===dialog){let r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});render();

